    foodSafety: { allergens: ["dairy"], safeStorage: "Refrigerate up to 72 hours. Richness matures overnight.", safeStorageMalayalam: "ഫ്രിഡ്ജിൽ 3 ദിവസം സൂക്ഷിക്കാം.", internalTemp: "82°C (180°F)", handlingTips: "Use kitchen tongs to handle the hot charcoal ember safely." },
