    instructions: [
      { stepNumber: 1, title: "Soak and Boil Ker Sangri", text: "Rinse dried ker and sangri thoroughly 4 times to remove desert dust. Soak in water for 6 to 8 hours. Pressure cook with salt for 1 whistle until tender but holding shape. Drain completely.", textMalayalam: "കേറും സാംഗ്രിയും നന്നായി കഴുകി 6-8 മണിക്കൂർ കുതിർത്തു പ്രഷർ കുക്കറിൽ ഒരു വിസിൽ വരുന്നതുവരെ വേവിക്കുക.", timerMinutes: 15, technique: "Hydration and Boiling" },
      { stepNumber: 2, title: "Temper Spices in Mustard Oil", text: "Heat mustard oil in a kadai to smoking point. Reduce heat, add hing, cumin seeds, whole dried red chilies, and turmeric.", textMalayalam: "കടുകെണ്ണ പുകയുന്ന ചൂടിൽ കായവും ജീരകവും വറ്റൽമുളകും മൂപ്പിക്കുക.", timerMinutes: 3 },
      { stepNumber: 3, title: "Stir Fry Desert Botanicals", text: "Add drained ker and sangri. Stir fry over medium heat for 6 minutes, allowing the beans to coat in pungent mustard oil.", textMalayalam: "വെള്ളം കളഞ്ഞ കേറും സാംഗ്രിയും ചേർത്ത് 6 മിനിറ്റ് ഇളക്കി വഴറ്റുക.", timerMinutes: 6 },
      { stepNumber: 4, title: "Season with Amchur and Raisins", text: "Add amchur, coriander powder, chili powder, and sweet raisins. Toss for 4 minutes until evenly spiced and glossy. Serve at room temperature with hot bajra (pearl millet) rotis.", textMalayalam: "മാങ്ങാപ്പൊടിയും മുളകുപൊടിയും ഉണക്കമുന്തിരിയും ചേർത്ത് 4 മിനിറ്റ് വഴറ്റി ബജ്റ റൊട്ടിയോടൊപ്പം വിളമ്പുക.", timerMinutes: 4, tip: "Ker Sangri acts like a natural pickle and tastes even better 2 days after cooking." },
    ],
    nutrition: { calories: 210, protein: 6, carbs: 24, fat: 11, fiber: 8 },
    foodSafety: { allergens: [], safeStorage: "Due to high spice and mustard oil, keeps for up to 8 days at room temperature without refrigeration.", safeStorageMalayalam: "ഫ്രിഡ്ജിൽ വെക്കാതെ തന്നെ 8 ദിവസം കേടുകൂടാതെ ഇരിക്കും.", handlingTips: "Thoroughly rinse the dried wild botanicals before soaking to remove fine wind-blown desert sand." },
