    foodSafety: { allergens: ["dairy"], safeStorage: "Refrigerate up to 48 hours in a sealed container.", safeStorageMalayalam: "ഫ്രിഡ്ജിൽ 48 മണിക്കൂർ സൂക്ഷിക്കാം.", handlingTips: "Taro root should be thoroughly boiled to prevent oxalates causing throat itchiness." },
    equipment: ["Earthen Cooking Pot (Kudua) / Deep Pan", "Tadka Ladle"],
